}

/// Performs glob expansion on `arg`. If the expansion found no matches or the pattern
/// is not a valid glob, then this returns the original string as the expansion result.
///
/// Note: This matches the default behavior of Bash, but is known to be
/// error-prone. We might want to change this behavior in the future.
fn expand_glob(arg: &str, cwd: &Path, span: Span) -> Result<Vec<String>, ShellError> {
    let mut has_star = false;
    let mut has_question = false;
    let mut has_open_bracket = false;
    let mut has_close_bracket = false;
    let mut max_consecutive_stars = 0usize;
    let mut prefix = PathBuf::new();
    let mut remainder = PathBuf::new();
    let mut collecting_prefix = true;
    let mut contains_parent_dir = false;
    let mut contains_cur_dir = false;

    for component in Path::new(arg).components() {
        match component {
            Component::Normal(part) => {
                let text = part.to_string_lossy();
                let mut glob_in_component = false;
                let mut consecutive_stars = 0usize;
                if !text.is_empty() {
                    for ch in text.chars() {
                        if ch == '*' {
                            has_star = true;
                            glob_in_component = true;
                            consecutive_stars += 1;
                            if consecutive_stars > max_consecutive_stars {
                                max_consecutive_stars = consecutive_stars;
                            }
                        } else if ch == '?' {
                            has_question = true;
                            glob_in_component = true;
                            consecutive_stars = 0;
                        } else if ch == '[' {
                            has_open_bracket = true;
                            glob_in_component = true;
                            consecutive_stars = 0;
                        } else if ch == ']' {
                            has_close_bracket = true;
                            consecutive_stars = 0;
                        } else {
                            consecutive_stars = 0;
                        }
                    }
                }
                if collecting_prefix {
                    if glob_in_component {
                        collecting_prefix = false;
                        remainder.push(component);
                    } else {
                        prefix.push(component);
                    }
                } else {
                    remainder.push(component);
                }
            }
            other => {
                contains_cur_dir |= other == Component::CurDir;
                contains_parent_dir |= other == Component::ParentDir;
                if collecting_prefix {
                    prefix.push(other);
                } else {
                    remainder.push(other);
                }
            }
        }
    }

    if max_consecutive_stars > 2 {
        return Ok(vec![arg.into()]);
    }

    let compiled_pattern = match nu_glob::Pattern::new(arg) {
        Ok(pattern) => pattern,
        Err(_) => return Ok(vec![arg.into()]),
    };

    let mut glob_parent = PathBuf::new();
    for component in nu_path::components(cwd) {
        match component {
            Component::Normal(part) if part.is_empty() => {}
            other => glob_parent.push(other),
        }
    }
    if glob_parent.as_os_str().is_empty() {
        glob_parent = cwd.to_path_buf();
    }

    let expanded_cwd = nu_path::expand_path_with(Path::new("."), &glob_parent, true);
    if expanded_cwd.as_path() == glob_parent.as_path() {
        glob_parent = expanded_cwd;
    }

    let has_glob_metachar = [has_star, has_question, has_open_bracket, has_close_bracket]
        .into_iter()
        .any(|flag| flag);
    if remainder.as_os_str().is_empty() && !has_glob_metachar {
        if let Ok(canonical_parent) = nu_path::canonicalize_with(&glob_parent, &glob_parent) {
            if canonical_parent == glob_parent {
                glob_parent = canonical_parent;
            }
        }
    }

    let should_expand_prefix = [contains_parent_dir, contains_cur_dir, prefix.is_relative()]
        .into_iter()
        .any(|flag| flag);
    let expanded_prefix = if prefix.as_os_str().is_empty() {
        glob_parent.clone()
    } else if should_expand_prefix {
        nu_path::expand_path_with(&prefix, &glob_parent, false)
    } else {
        prefix.clone()
    };

    let glob_input = if has_glob_metachar {
        compiled_pattern.as_str().to_string()
    } else {
        nu_glob::Pattern::escape(compiled_pattern.as_str())
    };

    let glob_scope = if Path::new(arg).is_absolute() {
        if remainder.as_os_str().is_empty() {
            glob_parent.as_path()
        } else {
            expanded_prefix.as_path()
        }
    } else {
        glob_parent.as_path()
    };

    let options = nu_glob::MatchOptions::default();
    let Ok(paths) = nu_glob::glob_with_parent(&glob_input, options, glob_scope) else {
        return Ok(vec![arg.into()]);
    };

    let mut result = vec![];
    for path in paths {
        let path = path.map_err(|err| ShellError::IOErrorSpanned {
            msg: format!("{}: {:?}", err.path().display(), err.error()),
            span,
        })?;
        // Strip PWD from the resulting paths if possible.
        let path_stripped = path.strip_prefix(cwd).unwrap_or(&path);
        let path_string = path_stripped.to_string_lossy().to_string();
        result.push(path_string);
    }

    if result.is_empty() {
        if arg.is_empty() {
            result.push(arg.to_string());
        } else {
            let fallback = Path::new(arg);
            let mut reconstructed = PathBuf::new();
            for component in nu_path::components(fallback) {
                match component {
                    Component::Normal(part) => {
                        if part.is_empty() {
                            reconstructed.push("");
                        } else {
                            reconstructed.push(part);
                        }
                    }
                    other => {
                        reconstructed.push(other);
                    }
                }
            }
            if reconstructed.as_os_str() == fallback.as_os_str() {
                result.push(reconstructed.to_string_lossy().into_owned());

metadata.output:
            },
            Example {
                description: "Redirect stdout from an external command into the pipeline",
                example: r#"run-external "echo" "-n" "hello" | split chars"#,
                result: None,
            },
            Example {
                description: "Redirect stderr from an external command into the pipeline",
                example: r#"run-external "nu" "-c" "print -e hello" e>| split chars"#,
                result: None,
            },
        ]
    }
}

/// Removes surrounding quotes from a string. Doesn't remove quotes from raw
/// strings. Returns the original string if it doesn't have matching quotes.
fn remove_quotes(s: &str) -> &str {
    let quoted_by_double_quotes = s.len() >= 2 && s.starts_with('"') && s.ends_with('"');
    let quoted_by_single_quotes = s.len() >= 2 && s.starts_with('\'') && s.ends_with('\'');
    let quoted_by_backticks = s.len() >= 2 && s.starts_with('`') && s.ends_with('`');
    if quoted_by_double_quotes || quoted_by_single_quotes || quoted_by_backticks {
        &s[1..s.len() - 1]
    } else {
        s
    }
}

/// Evaluate all arguments from a call, performing expansions when necessary.
pub fn eval_arguments_from_call(
    engine_state: &EngineState,
    stack: &mut Stack,
    call: &Call,
) -> Result<Vec<Spanned<String>>, ShellError> {
    let cwd = engine_state.cwd(Some(stack))?;
    let mut args: Vec<Spanned<String>> = vec![];
    for (expr, spread) in call.rest_iter(1) {
        if is_bare_string(expr) {
            // If `expr` is a bare string, perform tilde-expansion,
            // glob-expansion, and inner-quotes-removal, in that order.
            for arg in eval_argument(engine_state, stack, expr, spread)? {
                let tilde_expanded = expand_tilde(&arg);
                for glob_expanded in expand_glob(&tilde_expanded, &cwd, expr.span)? {
                    let inner_quotes_removed = remove_inner_quotes(&glob_expanded);
                    args.push(inner_quotes_removed.into_owned().into_spanned(expr.span));
                }
            }
        } else {
            for arg in eval_argument(engine_state, stack, expr, spread)? {
                args.push(arg.into_spanned(expr.span));
            }
        }
    }
    Ok(args)
}

